await fournisseur
  .given("le produit 42 existe")
  .uponReceiving("une demande du produit 42")
  .withRequest({ method: "GET", path: "/produits/42" })
  .willRespondWith({
    status: 200,
    body: { id: like(42), nom: like("Vélo"), prix: like(499.9) },
  })
  .executeTest(async (mock) => {
    const p = await new ClientCatalogue(mock.url).produit(42);
    expect(p.nom).toBe("Vélo");
  });

